    this.filter,
    this.source,
    this.customLabel,
    this.labelId,
    this.metadata,
  });

  /// The column's ID.
  final String? id;
  /// The column's name. This is displayed in the view header.
  final String? name;
  /// The column's description.
  final String? description;
  /// The column's field in the entity.
  final String? field;
  /// Whether the column is sortable.
  final bool? sortable;
  /// Whether the column is hideable.
  final bool? hideable;
  /// Whether the column is visible by default.
  final bool? defaultVisible;
  /// The data type of the column's value.
  final String? dataType;
  /// The column's semantic type. It can be `computed`, or other primitive types.
  final String? semanticType;
  /// The column's context. It can be `display` or `generic`.
  final String? context;
  /// A computed column's details. Only available if the column's `semantic_type` is `computed`.
  final Map<String, dynamic>? computed;
  /// The relationship details. Only available for relationship columns.
  final Map<String, dynamic>? relationship;
  /// The column's sort order in the default view configuration.
  final num? defaultOrder;
  /// The column's category.
  final String? category;
  /// The column's render mode.
  final String? renderMode;
  /// The column's filter.
  final Map<String, dynamic>? filter;
  /// The column's source details. Only available if the column is from a source.
  final Map<String, dynamic>? source;
  /// Whether the column has a custom label.
  final bool? customLabel;
  /// The ID of the column's label, if it has a custom label.
  final String? labelId;
  /// The column's metadata.
  final Map<String, dynamic>? metadata;

  factory AdminColumn.fromJson(Map<String, dynamic> json) => AdminColumn(
    id: json["id"] as String?,
    name: json["name"] as String?,
    description: json["description"] as String?,
    field: json["field"] as String?,
    sortable: json["sortable"] as bool?,
    hideable: json["hideable"] as bool?,
    defaultVisible: json["default_visible"] as bool?,
    dataType: json["data_type"] as String?,
    semanticType: json["semantic_type"] as String?,
    context: json["context"] as String?,
    computed: json["computed"] as Map<String, dynamic>?,
    relationship: json["relationship"] as Map<String, dynamic>?,
    defaultOrder: json["default_order"] as num?,
    category: json["category"] as String?,
    renderMode: json["render_mode"] as String?,
    filter: json["filter"] as Map<String, dynamic>?,
    source: json["source"] as Map<String, dynamic>?,
    customLabel: json["custom_label"] as bool?,
    labelId: json["label_id"] as String?,
    metadata: json["metadata"] as Map<String, dynamic>?,
  );

  Map<String, dynamic> toJson() => {
    if (id != null) "id": id!,
    if (name != null) "name": name!,
    if (description != null) "description": description!,
    if (field != null) "field": field!,
    if (sortable != null) "sortable": sortable!,
    if (hideable != null) "hideable": hideable!,
    if (defaultVisible != null) "default_visible": defaultVisible!,
    if (dataType != null) "data_type": dataType!,
    if (semanticType != null) "semantic_type": semanticType!,
    if (context != null) "context": context!,
    if (computed != null) "computed": computed!,
    if (relationship != null) "relationship": relationship!,
    if (defaultOrder != null) "default_order": defaultOrder!,
    if (category != null) "category": category!,
    if (renderMode != null) "render_mode": renderMode!,
    if (filter != null) "filter": filter!,
    if (source != null) "source": source!,
    if (customLabel != null) "custom_label": customLabel!,
    if (labelId != null) "label_id": labelId!,
    if (metadata != null) "metadata": metadata!,
  };
}
